106	func runDistill(ctx context.Context, cmd *cobra.Command, opts Options, distillOpts distillCommandOptions, target string) error {
107		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
108		if err != nil {
109			return err
110		}
111		if !local {
112			return fmt.Errorf("distill requires a local repository path: %s", target)
113		}
114		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
115		if err != nil {
116			return err
117		}
118		if distillOpts.agent == "auto" {
119			distillOpts.agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
120		}
121		if distillOpts.agent == "none" {
122			return errors.New("distillation requires an agent (codex or claude-code); none found on PATH")
123		}
124		if distillOpts.run == nil {
125			distillOpts.run = execDistillAgent
126		}
127		source, err := runDistillForBrain(ctx, repoDir, storage.BrainDir, distillOpts, opts.Now().UTC())
128		if err != nil {
129			return err
130		}
131		if distillOpts.json {
132			data, err := json.MarshalIndent(source, "", "  ")
133			if err != nil {
134				return err
135			}
136			fmt.Fprintln(cmd.OutOrStdout(), string(data))
137			return nil
138		}
139		fmt.Fprintf(cmd.OutOrStdout(), "distilled %d facts (%d distilled, %d authored, %d superseded) across %d branch(es) from %d chunks; %d proposals queued for review\n",
140			source.Facts, source.Distilled, source.Authored, source.Superseded, len(source.Branches), source.ChunksScanned, source.Proposals)
141		return nil
142	}
143	
144	// runDistillForBrain is the agent-driven distillation engine, operating on an
145	// already-exported brain directory. It enumerates sessions chronologically,
146	// chunks each transcript, runs the agent per chunk, merges the resulting facts
147	// into per-branch stores, and records the fact source on the brain manifest.
148	// repoDir is the working directory the agent runs in (sandboxed read-only).
149	func runDistillForBrain(ctx context.Context, repoDir, brainDir string, distillOpts distillCommandOptions, now time.Time) (*factSourceManifest, error) {
150		manifest, err := loadBrainManifest(brainDir)
151		if err != nil {
152			return nil, err
153		}
154		if manifest.Sources == nil || manifest.Sources.Sessions == nil || len(manifest.Sources.Sessions.Sessions) == 0 {
155			return nil, errors.New("no exported sessions; run `entire brain refresh` first")
156		}
157		if distillOpts.run == nil {
158			return nil, errors.New("distill: no agent runner configured")
159		}
160		if distillOpts.maxChunkBytes <= 0 {
161			distillOpts.maxChunkBytes = defaultDistillChunkSize
162		}
163	
164		taxonomy, err := loadFactTaxonomy(brainDir, now)
165		if err != nil {
166			return nil, err
167		}
168		prompt, err := renderDistillPrompt(taxonomy)
169		if err != nil {
170			return nil, err
171		}
172		args, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, prompt)
173		if err != nil {
174			return nil, err
175		}
176		reconcileArgs, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, reconcilePrompt())
177		if err != nil {
178			return nil, err
179		}
180		threshold := distillOpts.confidenceThreshold
181		if threshold <= 0 {
182			threshold = defaultFactConfidenceThreshold
183		}
184	
185		sessions := append([]exportSession(nil), manifest.Sources.Sessions.Sessions...)
186		// Chronological order so any future supersession chain reconstructs
187		// deterministically regardless of incremental vs --force.
188		sort.SliceStable(sessions, func(i, j int) bool { return sessions[i].CreatedAt.Before(sessions[j].CreatedAt) })
189	
190		prevCache := loadDistillCache(brainDir)
191		newCache := distillCache{Version: distillCacheVersion, Sessions: make(map[string]string, len(sessions))}
192	
193		byBranch := map[string][]factRecord{}
194		proposalsByBranch := map[string][]factProposal{}
195		loaded := map[string]bool{}
196		var warnings []string
197		chunksScanned, chunksDistilled := 0, 0
198	
199		// ensureBranch lazily loads a branch's existing facts. On --force the
200		// previously distilled facts are dropped so they are rebuilt from scratch;
201		// authored facts are always preserved.
202		ensureBranch := func(branch string) {
203			if loaded[branch] {
204				return
205			}
206			existing, loadErr := loadFacts(brainDir, branch)
207			if loadErr != nil {
208				warnings = append(warnings, fmt.Sprintf("load facts for %s: %v", branch, loadErr))
209			}
210			if distillOpts.force {
211				kept := existing[:0]
212				for _, record := range existing {
213					if record.Origin != factOriginDistilled {
214						kept = append(kept, record)
215					}
216				}
217				existing = kept
218			}
219			byBranch[branch] = existing
220			loaded[branch] = true
221		}
222	
223		for _, session := range sessions {
224			if distillOpts.branch != "" && session.Branch != distillOpts.branch {
225				continue
226			}
227			branch := session.Branch
228			if branch == "" {
229				branch = strings.TrimSpace(manifest.DefaultBranch)
230			}
231			if branch == "" {
232				branch = distillDefaultBranch
233			}
234			ensureBranch(branch)
235	
236			// Read the transcript before the cache check so the fingerprint can hash
237			// the actual bytes: a re-export that rewrites the same path with different
238			// content (e.g. compact vs raw mode, or an exporter fix) under the same
239			// checkpoint must invalidate the cache and re-run the agent.
240			content, readErr := readBrainRelativeFile(brainDir, session.TranscriptPath)
241			if readErr != nil {
242				warnings = append(warnings, fmt.Sprintf("read transcript %s: %v", session.TranscriptPath, readErr))
243				continue // not cached: retried next run
244			}
245	
246			fingerprint := distillSessionFingerprint(session, branch, content)
247			if !distillOpts.force {
248				if prev, ok := prevCache.Sessions[session.SessionID]; ok && prev == fingerprint {
249					newCache.Sessions[session.SessionID] = prev // unchanged; retain in cache and keep existing facts
250					continue
251				}
252			}
253	
254			chunks := chunkTranscript(content, distillOpts.maxChunkBytes)
255			sessionFailed := false
256			for _, chunk := range chunks {
257				chunksScanned++
258				anchor := factAnchor{
259					SessionID:    session.SessionID,
260					CheckpointID: session.LatestCheckpoint,
261					Transcript:   filepath.ToSlash(session.TranscriptPath),
262					Line:         chunk.StartLine,
263				}
264				out, runErr := distillOpts.run(ctx, repoDir, args, []byte(chunk.Text), distillOpts.timeout)
265				if runErr != nil {
266					warnings = append(warnings, fmt.Sprintf("agent failed on %s:%d: %v", session.SessionID, chunk.StartLine, runErr))
267					sessionFailed = true
268					continue
269				}
270				records, chunkWarnings := distilledFactsFromOutput(out, taxonomy, anchor, branch, now)
271				warnings = append(warnings, chunkWarnings...)
272				if len(records) == 0 {
273					continue
274				}
275				chunksDistilled++
276				// Reconcile the chunk's candidates against the branch's active facts
277				// so near-duplicates merge and contradictions supersede instead of
278				// piling up. Low-confidence decisions are queued for review.
279				actions, recWarnings := reconcileChunkCandidates(ctx, distillOpts.run, reconcileArgs, records, byBranch[branch], repoDir, distillOpts.timeout)
280				warnings = append(warnings, recWarnings...)
281				var chunkProposals []factProposal
282				byBranch[branch], chunkProposals = applyFactActions(byBranch[branch], actions, threshold, now)
283				proposalsByBranch[branch] = append(proposalsByBranch[branch], chunkProposals...)
284			}
285			// Only cache a session as distilled when every chunk succeeded, so a
286			// session whose agent calls failed is retried on the next run rather
287			// than being silently treated as done.
288			if !sessionFailed {
289				newCache.Sessions[session.SessionID] = fingerprint
290			}
291		}
292	
293		warnings = capWarnings(warnings, maxDistillWarnings)
294	
295		for branch, records := range byBranch {
296			if err := writeFacts(brainDir, branch, records); err != nil {
297				return nil, err
298			}
299			// Union this run's proposals with any already queued (a --force rebuild
300			// starts fresh since it rebuilds the distilled facts), then persist.
301			var prior []factProposal
302			if !distillOpts.force {
303				if loadedProposals, loadErr := loadFactProposals(brainDir, branch); loadErr != nil {
304					warnings = append(warnings, fmt.Sprintf("load proposals for %s: %v", branch, loadErr))
305				} else {
306					prior = loadedProposals
307				}
308			}
309			merged := dedupeProposals(append(prior, proposalsByBranch[branch]...))
310			if err := writeFactProposals(brainDir, branch, merged); err != nil {
311				return nil, err
312			}
313		}
314		if err := writeFactTaxonomy(brainDir, taxonomy); err != nil {
315			return nil, err
316		}
317		saveDistillCache(brainDir, newCache)
318	
319		// Summarize the manifest from the whole on-disk store, not just the branches
320		// touched this run. A branch-limited (`--branch`) or incremental run only
321		// loads a subset into byBranch; folding that subset into the manifest would
322		// drop counts/branches/proposals for facts that still exist on other
323		// branches. Re-reading the store after writing keeps sources.facts whole.
324		allBranches, err := loadAllFactBranches(brainDir)
325		if err != nil {
326			return nil, err
327		}
328		branchNames := make([]string, 0, len(allBranches))
329		for branch := range allBranches {
330			branchNames = append(branchNames, branch)
331		}
332		totalProposals := countFactProposals(brainDir, branchNames)
333	
334		source := summarizeFactSource(now, allBranches, chunksScanned, chunksDistilled, totalProposals, warnings)
335		if manifest.Sources == nil {
336			manifest.Sources = &brainSources{}
337		}
338		manifest.Sources.Facts = source
339		if manifest.GeneratedAt.IsZero() {
340			manifest.GeneratedAt = now
341		}
342		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
343			return nil, err
344		}
345		return source, nil
346	}
347	
348	// chunkTranscript splits a transcript into line-numbered chunks no larger than
349	// maxBytes (measured on the rendered, line-numbered text). A single line that
350	// exceeds maxBytes still becomes its own chunk rather than being dropped, so no
351	// content is silently lost. Blank input yields no chunks.
352	func chunkTranscript(content string, maxBytes int) []transcriptChunk {
353		if maxBytes <= 0 {
354			maxBytes = defaultDistillChunkSize
355		}
356		lines := strings.Split(content, "\n")
357		var chunks []transcriptChunk
358		var buf strings.Builder
359		startLine := 0
360		lineNo := 0
361		flush := func(endLine int) {
362			if buf.Len() == 0 {
363				return
364			}
365			chunks = append(chunks, transcriptChunk{StartLine: startLine, EndLine: endLine, Text: buf.String()})
366			buf.Reset()
367			startLine = 0
368		}
369		for _, line := range lines {
370			lineNo++
371			if strings.TrimSpace(line) == "" {
372				continue
373			}
374			rendered := fmt.Sprintf("%d\t%s\n", lineNo, line)
375			if buf.Len() > 0 && buf.Len()+len(rendered) > maxBytes {
376				flush(lineNo - 1)
377			}
378			if buf.Len() == 0 {
379				startLine = lineNo
380			}
381			buf.WriteString(rendered)
382		}
383		flush(lineNo)
384		return chunks
385	}
386	
387	// distillSessionFingerprint is the incremental-skip signal for one session. It
388	// hashes the session identity (id, latest checkpoint, transcript path, resolved
389	// branch) together with a digest of the transcript bytes, so any content change
390	// — even one that keeps the same checkpoint, such as a compact↔raw re-export or
391	// an exporter fix — invalidates the cache and forces a re-distill. The branch is
392	// the *resolved* one the facts are written under (session.Branch may be empty
393	// and fall back to the manifest default), so a default-branch change re-keys the
394	// session instead of letting a stale cache skip it.
395	func distillSessionFingerprint(session exportSession, branch, content string) string {
396		contentSum := sha256.Sum256([]byte(content))
397		sum := sha256.Sum256([]byte(strings.Join([]string{
398			session.SessionID,
399			session.LatestCheckpoint,
400			filepath.ToSlash(session.TranscriptPath),
401			branch,
402			hex.EncodeToString(contentSum[:]),
403		}, "\x00")))
404		return "sha256:" + hex.EncodeToString(sum[:])
405	}
406	
407	// readBrainRelativeFile reads a brain-relative path, rejecting absolute paths
408	// and parent-directory escapes so a manifest-supplied path cannot read outside
409	// the brain directory.
410	func readBrainRelativeFile(brainDir, rel string) (string, error) {
411		clean := filepath.Clean(filepath.FromSlash(rel))
412		if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
413			return "", fmt.Errorf("unsafe transcript path: %s", rel)
414		}
415		data, err := os.ReadFile(filepath.Join(brainDir, clean))
416		if err != nil {
417			return "", err
418		}
419		return string(data), nil
420	}
421	
422	// loadDistillCache reads the incremental cache, always returning a usable value:
423	// any read/parse error or version mismatch yields an empty cache so the next
424	// run simply re-distills everything.
425	func loadDistillCache(brainDir string) distillCache {
426		empty := distillCache{Version: distillCacheVersion, Sessions: map[string]string{}}
427		data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)))
428		if err != nil {
429			return empty
430		}
431		var cache distillCache
432		if err := json.Unmarshal(data, &cache); err != nil || cache.Version != distillCacheVersion || cache.Sessions == nil {
433			return empty
434		}
435		return cache
436	}
437	
438	// saveDistillCache persists the incremental cache. Failure is non-fatal: a
439	// missing cache only costs a full re-distillation next run.
440	func saveDistillCache(brainDir string, cache distillCache) {
441		data, err := json.MarshalIndent(cache, "", "  ")
442		if err != nil {
443			return
444		}
445		dir := filepath.Join(brainDir, factsDirName)
446		if err := os.MkdirAll(dir, 0o700); err != nil {
447			return
448		}
449		_ = writeFileAtomic(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)), append(data, '\n'), 0o600)
450	}
451	
452	// execDistillAgent is the real distillAgentRunner: it runs the agent with the
453	// transcript chunk on stdin and returns stdout, bounded by a timeout and an
454	// output-size cap.
455	func execDistillAgent(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
456		if len(args) == 0 {
457			return "", errors.New("distill: empty agent command")
458		}
459		runCtx, cancel := context.WithTimeout(ctx, timeout)
460		defer cancel()
461		command := exec.CommandContext(runCtx, args[0], args[1:]...)
462		command.Dir = dir
463		command.Stdin = bytes.NewReader(input)
464		var stdout, stderr bytes.Buffer
465		command.Stdout = &stdout
466		command.Stderr = &stderr
467		err := command.Run()
468		if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
469			return "", fmt.Errorf("agent timed out after %s", timeout)
470		}
471		if err != nil {
472			warning := strings.TrimSpace(stderr.String())
473			if warning == "" {
474				warning = strings.TrimSpace(stdout.String())
475			}
476			return "", fmt.Errorf("agent failed: %w: %s", err, truncateAgentWarning(warning))
477		}
478		if stdout.Len() > distillMaxOutputBytes {
479			return "", fmt.Errorf("agent output exceeds %d bytes", distillMaxOutputBytes)
480		}
481		return stdout.String(), nil
482	}
483

