SESS=/Users/thomi/.local/share/entire/plugins/data/brain/repos/gh/ashtom/entire-sem/sessions
python3 -c "
import os,glob,json
CHUNK=48*1024

def text_blocks(content):
    if isinstance(content,str): return content
    if isinstance(content,list):
        parts=[]
        for it in content:
            if not isinstance(it,dict): continue
            t=it.get('type')
            if t in ('tool_use','tool_result'): continue
            for k in ('text','input_text','output_text','content'):
                v=it.get(k)
                if isinstance(v,str) and v.strip(): parts.append(v); break
        return ' '.join(parts)
    return ''

def keep(obj):
    t=obj.get('type')
    if t=='agent_message': return obj.get('message','') or ''
    if t=='event_msg':
        p=obj.get('payload') or {}; pt=p.get('type')
        if pt in ('agent_message','user_message'): return p.get('message','') or ''
        if pt=='task_complete': return p.get('last_agent_message','') or ''
        return ''
    if t=='response_item':
        p=obj.get('payload') or {}
        if p.get('type')!='message': return ''
        if p.get('role') not in ('assistant','user'): return ''
        return text_blocks(p.get('content'))
    if t in ('assistant','user'):
        return text_blocks((obj.get('message') or {}).get('content'))
    if t in ('session_meta','turn_context','permission-mode','progress'): return ''
    return obj.get('message','') or '' if isinstance(obj.get('message'),str) else ''

def chunks_of(nonblank_lines):
    buf=0; c=0
    for i,l in enumerate(nonblank_lines,1):
        rendered=len(str(i))+1+len(l.encode())+1
        if buf>0 and buf+rendered>CHUNK: c+=1; buf=0
        buf+=rendered
    if buf>0: c+=1
    return c

files=sorted(glob.glob('$SESS/**/*.jsonl',recursive=True))
raw_bytes=proc_bytes=raw_chunks=proc_chunks=0
for f in files:
    raw_nonblank=[]; proc_nonblank=[]
    for line in open(f):
        line=line.rstrip('\n')
        if line.strip(): raw_nonblank.append(line)
        try: obj=json.loads(line)
        except: 
            if line.strip(): proc_nonblank.append(line)
            continue
        kept=' '.join(keep(obj).split())
        if kept.strip(): proc_nonblank.append(kept)
    raw_bytes+=sum(len(l.encode()) for l in raw_nonblank)
    proc_bytes+=sum(len(l.encode()) for l in proc_nonblank)
    raw_chunks+=chunks_of(raw_nonblank)
    proc_chunks+=chunks_of(proc_nonblank)

print(f'transcript bytes (non-blank):  raw {raw_bytes:>10,}  ->  filtered {proc_bytes:>9,}   ({100*proc_bytes/raw_bytes:.0f}% kept, -{100-100*proc_bytes/raw_bytes:.0f}%)')
print(f'chunks (= distill agent calls): raw {raw_chunks:>10}  ->  filtered {proc_chunks:>9}   ({raw_chunks}->{proc_chunks})')
print(f'worst-case calls incl reconcile: raw ~{2*raw_chunks:<9} ->  filtered ~{2*proc_chunks}')
"

